-- Permission vocabulary and system roles of the support module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the support permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('issue:create'::text, 'issue'::text, 'create'::text, 'Create issue'::text),
            ('issue:delete'::text, 'issue'::text, 'delete'::text, 'Delete issue'::text),
            ('issue:purge'::text, 'issue'::text, 'purge'::text, 'Purge issue'::text),
            ('issue:read'::text, 'issue'::text, 'read'::text, 'Read issue'::text),
            ('issue:restore'::text, 'issue'::text, 'restore'::text, 'Restore issue'::text),
            ('issue:update'::text, 'issue'::text, 'update'::text, 'Update issue'::text),
            ('service_level_agreement:create'::text, 'service_level_agreement'::text, 'create'::text, 'Create service level agreement'::text),
            ('service_level_agreement:delete'::text, 'service_level_agreement'::text, 'delete'::text, 'Delete service level agreement'::text),
            ('service_level_agreement:purge'::text, 'service_level_agreement'::text, 'purge'::text, 'Purge service level agreement'::text),
            ('service_level_agreement:read'::text, 'service_level_agreement'::text, 'read'::text, 'Read service level agreement'::text),
            ('service_level_agreement:restore'::text, 'service_level_agreement'::text, 'restore'::text, 'Restore service level agreement'::text),
            ('service_level_agreement:update'::text, 'service_level_agreement'::text, 'update'::text, 'Update service level agreement'::text),
            ('service_level_priority:create'::text, 'service_level_priority'::text, 'create'::text, 'Create service level priority'::text),
            ('service_level_priority:delete'::text, 'service_level_priority'::text, 'delete'::text, 'Delete service level priority'::text),
            ('service_level_priority:purge'::text, 'service_level_priority'::text, 'purge'::text, 'Purge service level priority'::text),
            ('service_level_priority:read'::text, 'service_level_priority'::text, 'read'::text, 'Read service level priority'::text),
            ('service_level_priority:restore'::text, 'service_level_priority'::text, 'restore'::text, 'Restore service level priority'::text),
            ('service_level_priority:update'::text, 'service_level_priority'::text, 'update'::text, 'Update service level priority'::text),
            ('warranty_claim:create'::text, 'warranty_claim'::text, 'create'::text, 'Create warranty claim'::text),
            ('warranty_claim:delete'::text, 'warranty_claim'::text, 'delete'::text, 'Delete warranty claim'::text),
            ('warranty_claim:purge'::text, 'warranty_claim'::text, 'purge'::text, 'Purge warranty claim'::text),
            ('warranty_claim:read'::text, 'warranty_claim'::text, 'read'::text, 'Read warranty claim'::text),
            ('warranty_claim:restore'::text, 'warranty_claim'::text, 'restore'::text, 'Restore warranty claim'::text),
            ('warranty_claim:update'::text, 'warranty_claim'::text, 'update'::text, 'Update warranty claim'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('issue:create'::text, 'issue'::text, 'create'::text, 'Create issue'::text),
            ('issue:delete'::text, 'issue'::text, 'delete'::text, 'Delete issue'::text),
            ('issue:purge'::text, 'issue'::text, 'purge'::text, 'Purge issue'::text),
            ('issue:read'::text, 'issue'::text, 'read'::text, 'Read issue'::text),
            ('issue:restore'::text, 'issue'::text, 'restore'::text, 'Restore issue'::text),
            ('issue:update'::text, 'issue'::text, 'update'::text, 'Update issue'::text),
            ('service_level_agreement:create'::text, 'service_level_agreement'::text, 'create'::text, 'Create service level agreement'::text),
            ('service_level_agreement:delete'::text, 'service_level_agreement'::text, 'delete'::text, 'Delete service level agreement'::text),
            ('service_level_agreement:purge'::text, 'service_level_agreement'::text, 'purge'::text, 'Purge service level agreement'::text),
            ('service_level_agreement:read'::text, 'service_level_agreement'::text, 'read'::text, 'Read service level agreement'::text),
            ('service_level_agreement:restore'::text, 'service_level_agreement'::text, 'restore'::text, 'Restore service level agreement'::text),
            ('service_level_agreement:update'::text, 'service_level_agreement'::text, 'update'::text, 'Update service level agreement'::text),
            ('service_level_priority:create'::text, 'service_level_priority'::text, 'create'::text, 'Create service level priority'::text),
            ('service_level_priority:delete'::text, 'service_level_priority'::text, 'delete'::text, 'Delete service level priority'::text),
            ('service_level_priority:purge'::text, 'service_level_priority'::text, 'purge'::text, 'Purge service level priority'::text),
            ('service_level_priority:read'::text, 'service_level_priority'::text, 'read'::text, 'Read service level priority'::text),
            ('service_level_priority:restore'::text, 'service_level_priority'::text, 'restore'::text, 'Restore service level priority'::text),
            ('service_level_priority:update'::text, 'service_level_priority'::text, 'update'::text, 'Update service level priority'::text),
            ('warranty_claim:create'::text, 'warranty_claim'::text, 'create'::text, 'Create warranty claim'::text),
            ('warranty_claim:delete'::text, 'warranty_claim'::text, 'delete'::text, 'Delete warranty claim'::text),
            ('warranty_claim:purge'::text, 'warranty_claim'::text, 'purge'::text, 'Purge warranty claim'::text),
            ('warranty_claim:read'::text, 'warranty_claim'::text, 'read'::text, 'Read warranty claim'::text),
            ('warranty_claim:restore'::text, 'warranty_claim'::text, 'restore'::text, 'Restore warranty claim'::text),
            ('warranty_claim:update'::text, 'warranty_claim'::text, 'update'::text, 'Update warranty claim'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
